import * as Phaser from 'phaser';
import {
  getGraphicsQualityController,
  type VisualImportance,
} from '../graphics/GraphicsQuality';
import { emissiveAlpha } from './EmissiveScale';

type CanvasTextureDrawCallback = (
  ctx: CanvasRenderingContext2D,
  canvas: Phaser.Textures.CanvasTexture,
) => void;

type RadialGradientStop = readonly [offset: number, color: string];

/**
 * Shared helpers for effect/particle systems.
 * Avoids duplicate circleZone/edgeZone implementations across FireSystem, SmokeSystem, etc.
 */

/** Random circular emit zone (Partikel spawnen zufällig innerhalb des Kreises). */
export function circleZone(r: number, quantity?: number): Phaser.Types.GameObjects.Particles.EmitZoneData {
  return {
    type:     'random',
    source:   new Phaser.Geom.Circle(0, 0, r),
    ...(quantity !== undefined && { quantity }),
  } as Phaser.Types.GameObjects.Particles.EmitZoneData;
}

/** Edge emit zone: Partikel spawnen gleichmäßig auf dem Kreisrand. */
export function edgeZone(r: number, quantity = 32): Phaser.Types.GameObjects.Particles.EmitZoneData {
  return {
    type:     'edge',
    source:   new Phaser.Geom.Circle(0, 0, r),
    quantity,
  } as Phaser.Types.GameObjects.Particles.EmitZoneData;
}

export function ensureCanvasTexture(
  textures: Phaser.Textures.TextureManager,
  key: string,
  width: number,
  height: number,
  draw: CanvasTextureDrawCallback,
): void {
  if (textures.exists(key)) return;

  const canvas = textures.createCanvas(key, width, height)!;
  draw(canvas.context, canvas);
  canvas.refresh();
}

export function fillRadialGradientTexture(
  textures: Phaser.Textures.TextureManager,
  key: string,
  size: number,
  stops: readonly RadialGradientStop[],
): void {
  ensureCanvasTexture(textures, key, size, size, (ctx) => {
    const center = size / 2;
    const gradient = ctx.createRadialGradient(center, center, 0, center, center, center);

    for (const [offset, color] of stops) {
      gradient.addColorStop(offset, color);
    }

    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, size, size);
  });
}

export function createEmitter(
  scene: Phaser.Scene,
  x: number,
  y: number,
  texture: string,
  config: Phaser.Types.GameObjects.Particles.ParticleEmitterConfig,
  depth: number,
  importance: VisualImportance = 'standard',
): Phaser.GameObjects.Particles.ParticleEmitter {
  const emitter = createQualityEmitter(scene, x, y, texture, config, importance);
  emitter.setDepth(depth);
  return emitter;
}

/**
 * Leert einen Emitter und neutralisiert die Koordinaten seiner gepoolten Partikel.
 * Phaser verschiebt `killAll()`-Partikel nur in den Dead-Pool; beim naechsten
 * `emitParticleAt()` wuerden ihre alten Koordinaten sonst erneut aufaddiert.
 */
export function killAllAndResetParticlePositions(
  emitter: Phaser.GameObjects.Particles.ParticleEmitter,
): void {
  emitter.killAll();
  emitter.forEachDead((particle) => {
    particle.x = 0;
    particle.y = 0;
  }, undefined);
}

export function createQualityEmitter(
  scene: Phaser.Scene,
  x: number,
  y: number,
  texture: string,
  config: Phaser.Types.GameObjects.Particles.ParticleEmitterConfig,
  importance: VisualImportance = 'standard',
): Phaser.GameObjects.Particles.ParticleEmitter {
  const emitter = scene.add.particles(x, y, texture, config);
  getGraphicsQualityController(scene)?.setEmitterImportance(emitter, importance);
  return emitter;
}

export function trackQualityEmitter(
  scene: Phaser.Scene,
  emitter: Phaser.GameObjects.Particles.ParticleEmitter,
  config: Phaser.Types.GameObjects.Particles.ParticleEmitterConfig,
  importance: VisualImportance = 'standard',
): Phaser.GameObjects.Particles.ParticleEmitter {
  getGraphicsQualityController(scene)?.trackEmitter(emitter, config, importance);
  return emitter;
}

export function setCircleEmitZone(
  emitter: Phaser.GameObjects.Particles.ParticleEmitter,
  radius: number,
  quantity?: number,
  replace = false,
): void {
  if (replace) {
    emitter.clearEmitZones();
  }

  emitter.addEmitZone(circleZone(radius, quantity));
}

/**
 * Schaltet ein Objekt additiv und dämpft es dabei um den Tagesfaktor.
 *
 * Ersetzt ein blosses `setBlendMode(Phaser.BlendModes.ADD)`. Der Umweg über die
 * Objekt-Alpha statt über die einzelnen Alphawerte ist Absicht: Phaser rechnet bei Shapes
 * `fillAlpha * alpha` und `strokeAlpha * alpha`, ein einziger Aufruf erfasst also Füllung
 * und Kontur gemeinsam – und bei Images ist es ohnehin dieselbe Zahl. Damit bleibt die
 * Umstellung an jeder Aufrufstelle ein Ein-Wort-Tausch, ohne Argumente umzuschreiben.
 *
 * **Nach** dem Setzen von Alpha, Füll- und Konturstil aufrufen und **vor** einem Tween,
 * der die Alpha animiert – der startet dann beim gedämpften Wert.
 */
export function makeAdditive<T extends Phaser.GameObjects.GameObject>(object: T): T {
  const target = object as T & {
    alpha: number;
    setBlendMode(mode: number): unknown;
    setAlpha(alpha: number): unknown;
  };
  target.setBlendMode(Phaser.BlendModes.ADD);
  target.setAlpha(emissiveAlpha(target.alpha));
  return object;
}

/**
 * Der zentrale Weg zu einer additiven Effektgrafik – und damit die Stelle, an der die
 * Tagesdämpfung greift. Ein ADD-Layer über hellem Mittagsboden klippt sonst zu einer
 * weißen Fläche; nachts (Faktor 1) bleibt der Wert unangetastet.
 */
export function configureAdditiveImage(
  image: Phaser.GameObjects.Image,
  depth: number,
  alpha: number,
  tint: number,
): Phaser.GameObjects.Image {
  return image
    .setBlendMode(Phaser.BlendModes.ADD)
    .setDepth(depth)
    .setAlpha(emissiveAlpha(alpha))
    .setTint(tint);
}

export function destroyEmitter(emitter: Phaser.GameObjects.Particles.ParticleEmitter): void {
  emitter.stop();
  emitter.destroy();
}

/**
 * Correctly updates a particle emitter's tint to a new array of colors.
 *
 * setParticleTint() only calls EmitterOp.onChange() which updates `current` but not
 * `propertyValue` or the emit method. For array tints, randomStaticValueEmit() reads
 * from `propertyValue`, so onChange() with an array causes staticValueEmit() to return
 * the array object — which JavaScript coerces to 0 (black) when used as a color.
 * Calling loadConfig() properly resets propertyValue, method, and onEmit.
 */
export function setEmitterTintArray(
  emitter: Phaser.GameObjects.Particles.ParticleEmitter,
  colors: number[],
): void {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  (emitter as any).ops?.tint?.loadConfig({ tint: colors });
}

/**
 * Correctly updates the emission direction of a radial particle emitter.
 *
 * Same trap as setEmitterTintArray(): setEmitterAngle() only calls EmitterOp.onChange(),
 * which updates `current` but neither `propertyValue` nor the emit method. A {min,max}
 * range passed that way never reaches randomRangedIntEmit(), so the emitter keeps its
 * previous (by default full-circle) direction. loadConfig() rebinds the emit method.
 */
export function setEmitterAngleRange(
  emitter: Phaser.GameObjects.Particles.ParticleEmitter,
  minDeg: number,
  maxDeg: number,
): void {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  (emitter as any).ops?.angle?.loadConfig({ angle: { min: minDeg, max: maxDeg } });
}

export function createSeededRandom(seed: number): () => number {
  let state = (seed >>> 0) || 0x6d2b79f5;

  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t ^= t + Math.imul(t ^ (t >>> 7), 61 | t);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function mixColors(colorA: number, colorB: number, amount: number): number {
  const t = Phaser.Math.Clamp(amount, 0, 1);
  const ar = (colorA >> 16) & 0xff;
  const ag = (colorA >> 8) & 0xff;
  const ab = colorA & 0xff;
  const br = (colorB >> 16) & 0xff;
  const bg = (colorB >> 8) & 0xff;
  const bb = colorB & 0xff;

  const rr = Math.round(Phaser.Math.Linear(ar, br, t));
  const rg = Math.round(Phaser.Math.Linear(ag, bg, t));
  const rb = Math.round(Phaser.Math.Linear(ab, bb, t));
  return (rr << 16) | (rg << 8) | rb;
}
